/* ============================================================
   1. Animations & Particles Init
   ============================================================ */

function loadAnimations() {
  const wow = new WOW({
    boxClass:     'wow',
    animateClass: 'animated',
    offset:       0,
    mobile:       false
  });

  particlesJS.load('particles-js',  './assets/particles.json', function() {});
  particlesJS.load('particles-js2', './assets/particles.json', function() {});

  wow.init();
}


/* ============================================================
   2. Page Load Sequence
   ============================================================ */

!function($) {
  'use strict';

  const sections = [
    '.navbar', '#home', '#about', '.quote-section',
    '#portfolio', '#trainings', '#achievements', '#contact', '.footer'
  ];

  $('body').css('background-color', '#090909');
  sections.forEach(s => $(s).css('display', 'none'));

  setTimeout(() => {
    $('.loader').fadeOut();
    sections.forEach(s => $(s).fadeIn());
    loadAnimations();

    setTimeout(() => {
      $('body').fadeIn().css('background-color', '#fff');
    }, 350);
  }, 2000);


  /* ============================================================
     3. Sticky Navbar
     ============================================================ */

  $(window).scroll(function() {
    const pastHero = $(window).scrollTop() + 50 >= window.innerHeight;
    $('.sticky').toggleClass('nav-sticky', pastHero);
  });


  /* ============================================================
     4. Smooth Scroll Navigation
     ============================================================ */

  $('.navbar-nav a').on('click', function(e) {
    const target = $(this);
    $('html, body').stop().animate(
      { scrollTop: $(target.attr('href')).offset().top },
      1500,
      'easeInOutExpo'
    );
    $('.navbar-nav').find('li.active').removeClass('active');
    target.parent('li').addClass('active');
    e.preventDefault();
  });

  $('#navbarCollapse').scrollspy({ offset: 70 });


  /* ============================================================
     5. Service Worker
     ============================================================ */

  let updatingWorker, reloading;

  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('/service-worker.js').then(reg => {
      reg.addEventListener('updatefound', () => {
        updatingWorker = reg.installing;
      });
    });

    navigator.serviceWorker.addEventListener('controllerchange', function() {
      if (!reloading) {
        window.location.reload();
        reloading = true;
      }
    });
  }


  /* ============================================================
     6. Tooltips & Tilt
     ============================================================ */

  $('[data-toggle="tooltip"]').tooltip({ trigger: 'hover' });

  VanillaTilt.init(document.querySelectorAll('.box'), {
    max:   25,
    speed: 400
  });

}(jQuery);


/* ============================================================
   7. Timeline Grants Panel
   ============================================================ */

function showGrants(stage) {
  document.querySelectorAll('.grants-section').forEach(el => el.style.display = 'none');
  const target = document.getElementById(stage);
  if (target) target.style.display = 'block';
}


/* ============================================================
   8. Outreach Tabs
   ============================================================ */

function showOutreach(id, btn) {
  document.querySelectorAll('.outreach-panel').forEach(p => p.style.display = 'none');
  document.querySelectorAll('.outreach-btn').forEach(b => b.classList.remove('active'));
  document.getElementById('outreach-' + id).style.display = 'block';
  btn.classList.add('active');
}


/* ============================================================
   9. Photo Gallery
   ============================================================ */

document.addEventListener('DOMContentLoaded', function() {

  // --- Grants default ---
  showGrants('grants-assistant_prof');

  // --- Gallery setup ---
  const slides       = document.querySelectorAll('.gallery-slide');
  const dotsContainer = document.getElementById('gallery-dots');

  if (!slides.length || !dotsContainer) return;

  let current = 0;
  let timer;

  slides.forEach((_, i) => {
    const dot = document.createElement('div');
    dot.className = 'gallery-dot' + (i === 0 ? ' active' : '');
    dot.onclick = () => goTo(i);
    dotsContainer.appendChild(dot);
  });

  function goTo(n) {
    slides[current].classList.remove('active');
    dotsContainer.children[current].classList.remove('active');
    current = (n + slides.length) % slides.length;
    slides[current].classList.add('active');
    dotsContainer.children[current].classList.add('active');
    resetTimer();
  }

  function resetTimer() {
    clearInterval(timer);
    timer = setInterval(() => goTo(current + 1), 4000);
  }

  window.moveGallery = function(dir) { goTo(current + dir); };

  resetTimer();

});